const form = $('Register An Activity').first().json;
const policy = $('Set Register Policy').first().json;
const checklist = $input.all().map(i => i.json).filter(c => c && c.field_key);
const vagueRetention = String(policy.vague_retention_phrases || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);
const vaguePurpose = String(policy.vague_purpose_phrases || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);
const val = k => String(form[k] == null ? '' : form[k]).trim();
const low = k => val(k).toLowerCase();
const findings = [];   // { field_key, issue, source, detail, severity: 'hard' | 'soft' }
const hard = (field_key, issue, detail) => findings.push({ field_key, issue, source: 'rules', detail, severity: 'hard' });
const soft = (field_key, issue, detail) => findings.push({ field_key, issue, source: 'rules', detail, severity: 'soft' });
let requiredCount = 0, presentCount = 0;
for (const c of checklist) {
  const isRequired = c.required === true || String(c.required).toLowerCase() === 'true';
  const minChars = Number(c.min_chars) || 1;
  const v = val(c.field_key);
  if (isRequired) requiredCount += 1;
  if (v.length >= minChars && !/^(n\/a|na|none|-|\?)$/i.test(v) || (c.field_key === 'recipients' && /^none$/i.test(v))) { if (isRequired) presentCount += 1; continue; }
  if (isRequired) hard(c.field_key, 'missing_field', c.label + ' is missing or too short (' + c.article + '). ' + String(c.guidance || ''));
}
// consistency rules
if (low('transfers_outside_eea') === 'yes' && /^(none|not applicable|)$/.test(low('transfer_safeguard'))) hard('transfer_safeguard', 'transfer_without_safeguard', 'Transfers outside the EEA are declared but no safeguard is named (Art. 44-49).');
if (low('transfers_outside_eea') === 'not sure') soft('transfers_outside_eea', 'transfer_unknown', 'Whether data leaves the EEA is not known; a person must find out.');
if (low('legal_basis') === 'not sure' || low('legal_basis') === '') hard('legal_basis', 'legal_basis_unknown', 'No legal basis chosen (Art. 6(1)).');
if (low('special_categories') === 'yes') {
  const t = (low('purposes') + ' ' + low('security_measures') + ' ' + low('legal_basis'));
  if (!/art\.? ?9|article 9|explicit consent|employment law|social security|vital interest|health ?care|medical diagnosis|public health|substantial public interest|legal claims/.test(t)) hard('legal_basis', 'special_category_condition_missing', 'Special categories are processed but no Art. 9(2) condition is stated anywhere in the record.');
}
if (low('special_categories') === 'not sure') soft('special_categories', 'special_category_unknown', 'Whether special categories are involved is not known; check the data categories.');
if (/legitimate interest/.test(low('legal_basis')) && !/interest|balanc|assessment|lia/.test(low('purposes') + ' ' + low('security_measures'))) soft('legal_basis', 'lia_not_described', 'Legitimate interests is chosen but no interest or balancing test is described (Art. 6(1)(f)).');
if (val('retention_period') && vagueRetention.some(p => low('retention_period').includes(p))) soft('retention_period', 'retention_vague', 'The retention period is not a period: "' + val('retention_period').slice(0, 80) + '" (Art. 30(1)(f)).');
if (val('purposes') && vaguePurpose.some(p => low('purposes').includes(p))) soft('purposes', 'purpose_vague', 'The purpose is generic: "' + val('purposes').slice(0, 80) + '" (Art. 30(1)(b)).');
if (low('controller_role') === 'processor') soft('controller_role', 'processor_record', 'Processors keep a processor record under Art. 30(2); this form is written for controller activities.');
const completeness = requiredCount ? Math.round(100 * presentCount / requiredCount) : 0;
let status, reason;
if (!checklist.length) { status = 'INCOMPLETE'; reason = 'the ropa_checklist table is empty, so nothing could be checked; run Set Up Tables first'; }
else if (findings.some(f => f.severity === 'hard')) { status = 'INCOMPLETE'; reason = findings.filter(f => f.severity === 'hard').length + ' required item(s) missing or inconsistent'; }
else if (findings.length) { status = 'REVIEW'; reason = findings.length + ' point(s) a person should look at'; }
else { status = 'COMPLETE'; reason = 'every Art. 30(1) item is filled and consistent by the rules'; }
const recordText = ['activity_name', 'owner_team', 'controller_role', 'purposes', 'legal_basis', 'data_subjects', 'data_categories', 'special_categories', 'recipients', 'transfers_outside_eea', 'transfer_safeguard', 'retention_period', 'security_measures'].map(k => k + ': ' + val(k)).join('\n');
const judgePrompt = 'RECORD OF PROCESSING (one field per line):\n' + recordText + '\n\nCHECKLIST (field_key: label; guidance):\n' + checklist.map(c => c.field_key + ': ' + c.label + '; ' + String(c.guidance || '')).join('\n') +
  '\n\nALREADY FOUND BY THE RULES (do not repeat): ' + (findings.map(f => f.field_key + '/' + f.issue).join(', ') || 'none') +
  '\n\nList any field whose answer does not do what the checklist asks, for example a purpose that is not specific, a retention that is not a period, a legal basis that does not fit the purpose, or a recipient list that names a country but no safeguard. For each, give the field_key, a short issue, and a verbatim quote (at least three words, copied exactly) from that field. If nothing more is wrong, return an empty list.';
return [{ json: {
  record_id: $execution.id, registered_at: new Date().toISOString(),
  activity_name: val('activity_name'), owner_team: val('owner_team'), controller_role: val('controller_role'), purposes: val('purposes'),
  legal_basis: val('legal_basis'), data_subjects: val('data_subjects'), data_categories: val('data_categories'), special_categories: val('special_categories'),
  recipients: val('recipients'), transfers_outside_eea: val('transfers_outside_eea'), transfer_safeguard: val('transfer_safeguard'),
  retention_period: val('retention_period'), security_measures: val('security_measures'),
  checklist_loaded: checklist.length, checklist_keys: checklist.map(c => c.field_key),
  required_count: requiredCount, present_count: presentCount, completeness,
  findings, rule_status: status, rule_reason: reason, record_text: recordText, judge_prompt: judgePrompt
} }];

const s = $('Check The Record').first().json;
const judgeItem = $input.first().json || {};
const out = judgeItem.output && typeof judgeItem.output === 'object' ? judgeItem.output : null;
let judgeStatus, judgeNote = '';
const added = [], rejected = [];
if (out && Array.isArray(out.issues)) {
  judgeStatus = 'answered'; judgeNote = String(out.note || '');
  const lower = String(s.record_text || '').toLowerCase();
  for (const a of out.issues) {
    const key = String((a && a.field_key) || '').trim();
    const quote = String((a && a.quote) || '').trim();
    const issue = String((a && a.issue) || '').trim().slice(0, 160);
    if (!s.checklist_keys.includes(key)) { rejected.push(key + ': unknown field'); continue; }
    if (quote.length < 8 || !lower.includes(quote.toLowerCase())) { rejected.push(key + ': quote not found in the record'); continue; }
    if (s.findings.some(f => f.field_key === key) || added.some(f => f.field_key === key)) { rejected.push(key + ': already found'); continue; }
    added.push({ field_key: key, issue: 'judge_' + (issue.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 40) || 'issue'), source: 'judge', detail: issue + ' (quoted: "' + quote.slice(0, 160) + '")', severity: 'soft' });
  }
} else {
  judgeStatus = 'did not answer';
  judgeNote = 'judge did not answer' + (judgeItem.error ? ': ' + String(judgeItem.error.message || judgeItem.error).slice(0, 160) : '');
}
const all = s.findings.concat(added);
let status = s.rule_status, reason = s.rule_reason;
if (status === 'COMPLETE' && added.length) { status = 'REVIEW'; reason = added.length + ' point(s) raised by the reviewer model, each with a quote'; }
const lines = all.map(f => '- ' + f.field_key + ' [' + f.source + ', ' + f.severity + ']: ' + f.detail);
if (rejected.length) lines.push('- Reviewer suggestions not counted: ' + rejected.join('; '));
lines.push('- Reviewer: ' + judgeStatus + (judgeNote ? ' (' + judgeNote.slice(0, 200) + ')' : ''));
lines.push('- Completeness: ' + s.present_count + ' of ' + s.required_count + ' required items filled (' + s.completeness + '%)');
const report = 'Status ' + status + ': ' + reason + '\n' + lines.join('\n');
return [{ json: Object.assign({}, s, {
  findings_all: all, missing_fields: all.filter(f => f.severity === 'hard').map(f => f.issue === 'missing_field' ? f.field_key : f.issue).join(', ') || 'none',
  judge_status: judgeStatus, judge_note: judgeNote, status, status_reason: reason, report
}) }];

const d = $('Combine Into A Status').first().json;
const rows = d.findings_all.map(f => ({ json: { record_id: d.record_id, activity_name: d.activity_name, field_key: f.field_key, issue: f.issue, source: f.source, detail: String(f.detail).slice(0, 400), found_at: d.registered_at } }));
if (!rows.length) rows.push({ json: { record_id: d.record_id, activity_name: d.activity_name, field_key: 'none', issue: 'none', source: 'rules', detail: 'no issue found; status ' + d.status, found_at: d.registered_at } });
return rows;

const policy = $('Set Digest Policy').first().json;
const days = Number(policy.lookback_days) || 7;
const cutoff = new Date(Date.now() - days * 86400 * 1000).toISOString();
const rows = $input.all().map(i => i.json).filter(r => r && r.registered_at);
const recent = rows.filter(r => String(r.registered_at) >= cutoff);
const by = {}; for (const r of rows) { const v = r.status || 'UNKNOWN'; by[v] = (by[v] || 0) + 1; }
const open = rows.filter(r => r.status === 'INCOMPLETE').map(r => r.activity_name + ' (missing: ' + String(r.missing_fields || 'none') + ')');
const quiet = recent.length === 0;
const needs = quiet ? Boolean(policy.post_when_quiet) : ((by.INCOMPLETE || 0) + (by.REVIEW || 0)) > 0;
const now = new Date().toISOString();
let summary = rows.length + ' activities in the register: ' + (by.COMPLETE || 0) + ' complete, ' + (by.REVIEW || 0) + ' to review, ' + (by.INCOMPLETE || 0) + ' incomplete. ' + recent.length + ' registered in the last ' + days + ' days.';
if (open.length) summary += ' Incomplete: ' + open.slice(0, 10).join('; ') + (open.length > 10 ? '; and ' + (open.length - 10) + ' more' : '') + '.';
if (quiet) summary += ' No new registrations this period; silence is not evidence that nothing new started.';
return [{ json: { digest_for: cutoff.slice(0, 10) + ' to ' + now.slice(0, 10), total: rows.length, recent: recent.length, complete: by.COMPLETE || 0, review: by.REVIEW || 0, incomplete: by.INCOMPLETE || 0, needs_attention: needs, summary } }];
